          {profile.educationLevel === 'jhs' && checkbox('isExistingEsc', 'edu-existing-esc', local('May Education Service Contracting (ESC) tuition subsidy ng DepEd-PEAC mula Grade 7 (para sa nagpapatuloy na estudyante)', 'Existing Education Service Contracting (ESC) tuition subsidy from DepEd-PEAC since Grade 7 (for continuing students)', 'Adunay ESC tuition subsidy gikan sa Grade 7', 'Addaan iti ESC tuition subsidy manipud Grade 7'))}
